CREATE TABLE "Record" ("id" TEXT NOT NULL PRIMARY KEY, "kind" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "data" JSONB NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "Record_kind_idx" ON "Record"("kind");
CREATE TABLE "Activity" ("id" TEXT NOT NULL PRIMARY KEY, "recordId" TEXT NOT NULL, "action" TEXT NOT NULL, "detail" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Activity_recordId_createdAt_idx" ON "Activity"("recordId", "createdAt");
CREATE TABLE "Operation" ("id" TEXT NOT NULL PRIMARY KEY, "result" JSONB NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
